import json, shutil, html, re
from pathlib import Path

ROOT=Path(__file__).parent
DATA=ROOT/'data'
PROFILE=json.loads((ROOT/'owner-profile.json').read_text(encoding='utf-8-sig'))
K=PROFILE['owner']
SITE_URL=PROFILE.get('site_url','https://YOUR-DOMAIN.example').rstrip('/')
def phone_link(v): return ''.join(c for c in v if c.isdigit() or c=='+')
projects=json.loads((DATA/'02-projects.json').read_text(encoding='utf-8'))['projects']
manifest=json.loads((DATA/'ASSET-MANIFEST.json').read_text(encoding='utf-8'))['projects']
man={x['id']:x for x in manifest}
unavailable={'dhofar-sooq'}
shown=[p for p in projects if p['id'] not in unavailable]
category_map={'Automotive':'Mobility','Business & Industry':'Business & Industrial','Coming Soon':'Professional Services','Commerce':'Commerce','Creative':'Creative','Digital Product':'Digital Products','Financial Services':'Finance & Property','Food & Dining':'Commerce','Learning':'Digital Products','Marketplace':'Marketplaces','Mobility':'Mobility','Professional Services':'Professional Services','Real Estate':'Finance & Property','Real Estate Finance':'Finance & Property','Technology':'Commerce'}
def category(p): return category_map.get(p['category'],p['category'])
def esc(x):
    english_only=re.sub(r'[\u0600-\u06ff\u0750-\u077f\u08a0-\u08ff\ufb50-\ufdff\ufe70-\ufeff]+','Arabic text',str(x or ''))
    return html.escape(english_only,quote=True)
def title(p): return 'BrainWave' if p['id']=='graduation-project-henna' else p['title']
def path_img(file): return '../../'+file.replace('\\','/')
def header(depth=0):
    prefix='../'*depth
    return f'''<a class="skip" href="#main">Skip to content</a><header class="top"><a class="mark" href="{prefix}index.html" aria-label="Kerollos Harby home"><i>KH</i><span>KEROLLOS HARBY</span></a><nav aria-label="Main navigation"><a href="{prefix}work/index.html">Work</a><a href="{prefix}about/index.html">About</a><a href="{prefix}contact/index.html">Contact</a></nav><a class="nav-cta" href="{prefix}contact/index.html">Start a conversation <b>↗</b></a></header>'''
def footer(depth=0):
    prefix='../'*depth
    return f'''<footer><div><a class="mark" href="{prefix}index.html"><i>KH</i><span>KEROLLOS HARBY</span></a><p>Digital experiences, across industries.</p></div><div class="footlinks"><a href="{prefix}work/index.html">Work</a><a href="{prefix}about/index.html">About</a><a href="{prefix}contact/index.html">Contact</a><a href="https://www.linkedin.com/in/kerollos-harby-a89a55230/" target="_blank" rel="noopener noreferrer">Kerollos on LinkedIn ↗</a></div><small>© 2026 Kerollos Harby · Project information reflects visible source websites.</small></footer>'''
def shell(title,desc,body,depth=0,extra=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#10120e"><title>{esc(title)} | Kerollos Harby</title><link rel="stylesheet" href="{'../'*depth}assets/site.css">{extra}</head><body>{header(depth)}{body}{footer(depth)}<script src="{'../'*depth}assets/site.js" defer></script></body></html>'''

ROOT.joinpath('assets').mkdir(exist_ok=True)

def card(p, i, depth=0):
    shots=man[p['id']]['screenshots']; img=path_img(p.get('cover_image') or shots[0]['file'])
    prefix='../'*depth
    search=' '.join([title(p),p['service_name'],p['category'],*p.get('verified_features',[])])
    image_class='mobile-project' if p['id']=='smart-dental-system' else ''
    return f'''<article class="project-card" data-search="{esc(search)}"><a href="{prefix}work/{esc(p['slug'])}/index.html"><div class="card-image {image_class}"><img src="{prefix}{esc(p.get('cover_image') or shots[0]['file'])}" alt="{esc(title(p))} project cover" loading="lazy"><span class="view">View case study ↗</span></div><div class="card-meta"><span>{esc(category(p))}</span><span>{i:02d}</span></div><h3>{esc(title(p))}</h3><p>{esc(p['one_line_hook'])}</p></a></article>'''

# Home
featured=([p for p in shown if p['id']=='smart-dental-system']+[p for p in shown if p['id'] not in ('graduation-project-henna','smart-dental-system')])[:8]
hero=next(p for p in shown if p['id']=='smart-dental-system').get('cover_image') or man['smart-dental-system']['screenshots'][0]['file']
body=f'''<main id="main"><section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> DIGITAL PORTFOLIO <span>· 2026</span></p><h1>Digital experiences<br>built to make a<br><em>strong first impression.</em></h1><p class="lede">A selected collection of websites and digital experiences across commerce, services, marketplaces, and business—each shaped around what its audience needs to find and do.</p><div class="actions"><a class="button lime" href="work/index.html">Explore the work <b>↘</b></a><a class="text-link" href="contact/index.html">Have a project in mind? Let’s talk <b>↗</b></a></div><div class="hero-byline"><span>KEROLLOS HARBY</span><span>DIGITAL PORTFOLIO · SELECTED WORK</span></div></div><div class="hero-visual"><img src="{hero}" alt="ONE dental app collage cover"><div class="image-stamp">A COLLECTION<br>OF DIGITAL WORK <b>↘</b></div><span class="hero-index">SELECTED PROJECTS · 01—{len(shown):02d}</span></div></section>
<section class="range"><span>RANGE</span><p>Commerce <i>·</i> Marketplaces <i>·</i> Professional services <i>·</i> Finance &amp; property <i>·</i> Mobility <i>·</i> Business</p><span>01 / 03</span></section>
<section class="section work-preview"><div class="section-head"><div><p class="eyebrow">SELECTED DIGITAL WORK</p><h2>Selected work<span class="lime-dot">.</span></h2></div><a class="text-link" href="work/index.html">Browse all projects <b>↗</b></a></div><div class="project-grid">{''.join(card(p,i+1) for i,p in enumerate(featured))}</div><div class="center"><a class="button outline" href="work/index.html">View all projects <b>↗</b></a></div></section>
<section class="about-band"><div><p class="eyebrow">THE APPROACH</p><h2>Different industries.<br><em>One clear experience.</em></h2></div><div><p>This collection spans online shops, professional services, marketplaces, mobility, and digital products. Explore what each website presents, how it guides visitors, and the details that make it distinct.</p><a class="text-link" href="about/index.html">About Kerollos <b>↗</b></a></div></section>
<section class="contact-band"><p class="eyebrow">OPEN TO THE NEXT IDEA</p><h2>Have a project<br>in mind?</h2><a class="button dark" href="contact/index.html">Let’s talk <b>↗</b></a><span class="contact-orbit">SAY<br>HELLO</span></section></main>'''
(ROOT/'index.html').write_text(shell('Digital portfolio','A selected collection of digital projects by Kerollos Harby.',body),encoding='utf-8')

# Work index with client-side search and category filters
cats=['All']+sorted(set(category(p) for p in shown))
buttons=''.join(f'<button class="filter" data-category="{esc(c)}" aria-pressed="{"true" if c=="All" else "false"}">{esc(c)}</button>' for c in cats)
cards=''.join(card(p,i+1,1) for i,p in enumerate(shown))
body=f'''<main id="main"><section class="page-hero"><p class="eyebrow">THE PROJECT INDEX · {len(shown):02d} PROJECTS</p><h1>Work that spans<br><em>many different worlds.</em></h1><p class="lede">Browse a varied collection of digital experiences. Search by name, service, or category.</p></section><section class="section index-section"><div class="search-row"><label class="searchbox"><span aria-hidden="true">⌕</span><span class="sr-only">Search projects</span><input id="project-search" type="search" placeholder="Search projects, services…" autocomplete="off"><kbd>/</kbd></label><span id="result-count" aria-live="polite">{len(shown)} projects</span></div><div class="filters" aria-label="Filter by category">{buttons}</div><div class="project-grid" id="project-grid">{cards}</div><p id="no-results" class="no-results" hidden>No projects match that search. <button id="reset-search">Clear filters</button></p><p class="muted note">Dhofar Sooq is omitted because the supplied website could not be reached and no service or screenshots could be verified.</p></section></main>'''
(ROOT/'work').mkdir(exist_ok=True)
(ROOT/'work'/'index.html').write_text(shell('Selected Work','Search and filter verified digital projects across multiple industries.',body,1),encoding='utf-8')

# Individual case studies
for ix,p in enumerate(shown,1):
    shots=man[p['id']]['screenshots']
    note=''
    if p['id']=='graduation-project-henna':
        note='<aside class="notice"><b>Naming mismatch</b><p>The supplied label says “Graduation Project Henna,” while the linked website currently presents BrainWave, a mind-map and blog product. This page describes only the visible BrainWave experience; no henna content was verified.</p></aside>'
    if p['id']=='excited':
        note='<aside class="notice"><b>Current site description</b><p>The website currently describes event planning and related services. These are presented as the site’s own descriptions, not independently verified delivery outcomes.</p></aside>'
    if p['id']=='car-motors':
        note='<aside class="notice"><b>Brand name clarification</b><p>The supplied project label was “Car Motors”; the linked website brands itself as Cairo Motors. This page uses the visible on-site brand.</p></aside>'
    if p['id']=='smart-dental-system':
        note='<aside class="notice"><b>App name and access</b><p>The owner identifies this application as ONE. The supplied dashboard link redirects signed-out visitors to a sign-in page branded Smart Dental System; the owner confirms that this is the same app. Sample information shown in its captures is fake.</p></aside>'
    live_label='Open the app · sign-in required' if p['id']=='smart-dental-system' else 'Visit the live project'
    features=''.join(f'<li>{esc(x)}</li>' for x in p.get('verified_features',[])[:8])
    feature_heading='WHAT THE APP OFFERS' if p['id']=='smart-dental-system' else ('WHAT THE SUPPLIED IMAGES SHOW' if not p.get('url') else 'WHAT THE WEBSITE OFFERS')
    attribution='This case study describes what the supplied captures show. Individual contribution has not been confirmed.' if not p.get('url') else 'This case study documents what the linked website presents. Individual contribution to this project has not been confirmed.'
    image_label='app capture' if p['id']=='smart-dental-system' else ('image' if not p.get('url') else 'website')
    journey=esc((p.get('visible_user_flows') or ['No single visitor flow could be confirmed from the available captures.'])[0])
    gallery=''.join(f'<figure><img src="{path_img(s["file"])}" alt="{esc(title(p))} {image_label}: {esc(s["label"])} ({esc(s["viewport"])} capture)" loading="lazy"><figcaption><span>{esc(s["label"])}</span><span>{esc(s["viewport"])}</span></figcaption></figure>' for s in shots)
    nextp=shown[(ix)%len(shown)]
    coverclass='mobile-cover' if p['id']=='smart-dental-system' else ''
    coverfile=p.get('cover_image') or shots[0]['file']
    coveralt='ONE dental app collage cover' if p['id']=='smart-dental-system' else f'{title(p)} website homepage capture'
    covercaption='Supplied ONE app collage · confirm reuse rights before public launch' if p['id']=='smart-dental-system' else 'Homepage · authentic source capture'
    body=f'''<main id="main"><section class="case-intro"><a class="back-link" href="../../work/index.html">← All projects</a><div class="case-kicker"><span>{esc(category(p))}</span><span>PROJECT {ix:02d} / {len(shown):02d}</span></div><h1>{esc(title(p))}</h1><p class="case-hook">{esc(p['one_line_hook'])}</p><div class="case-actions">{f'<a class="button lime" href="{esc(p['url'])}" target="_blank" rel="noopener noreferrer">{esc(live_label)} <b>↗</b></a>' if p.get('url') else '<span>No public website link was supplied.</span>'}<span>{'Source website' if p.get('url') else 'Owner-supplied images'} · captured {esc(p.get('capture_time_utc',''))[:10]}</span></div></section>{note}<figure class="case-cover {coverclass}"><img src="{path_img(coverfile)}" alt="{esc(coveralt)}" fetchpriority="high"><figcaption>{esc(covercaption)}</figcaption></figure><section class="case-content"><div class="case-about"><p class="eyebrow">WHAT IT IS</p><h2>{esc(p['service_name'])}</h2><p>{esc(p['what_it_does'])}</p><p class="attribution">{esc(attribution)}</p></div><div class="feature-list"><p class="eyebrow">{feature_heading}</p><ul>{features}</ul></div></section><section class="journey-block"><p class="eyebrow">VISITOR JOURNEY</p><p>{journey}</p></section><section class="gallery-section"><div class="section-head"><div><p class="eyebrow">AUTHENTIC SCREEN CAPTURES · {len(shots):02d}</p><h2>Inside the experience<span class="lime-dot">.</span></h2></div><p>Genuine, distinct screen captures supplied for this project. No screenshots have been fabricated or duplicated.</p></div><div class="gallery">{gallery}</div></section><section class="next-project"><div><p class="eyebrow">KEEP EXPLORING</p><h2>{esc(title(nextp))}</h2></div><a class="button outline" href="../{esc(nextp['slug'])}/index.html">Next case study <b>↗</b></a></section></main>'''
    folder=ROOT/'work'/p['slug'];folder.mkdir(exist_ok=True)
    extra=f'<meta property="og:title" content="{esc(p["title"])} — Digital portfolio"><meta property="og:description" content="{esc(p["one_line_hook"])}"><meta property="og:type" content="article"><meta property="og:image" content="{esc(path_img(p.get("cover_image") or shots[0]["file"]))}">'
    (folder/'index.html').write_text(shell(title(p),p['one_line_hook'],body,2,extra),encoding='utf-8')

# About and contact pages
body=f'''<main id="main"><section class="page-hero"><p class="eyebrow">ABOUT</p><h1>Curious about how<br><em>digital things work.</em></h1><p class="lede">I’m Kerollos Harby. This portfolio brings together websites and digital experiences across a range of industries.</p></section><section class="about-band about-page"><div><p class="eyebrow">A NOTE ON THIS COLLECTION</p><h2>Explore the work<br>on its own terms.</h2></div><div><p>Each project page is grounded in the visible content of its linked website and the supplied screen captures. The pages describe what those websites show; they don’t claim individual authorship, outcomes, or technologies that haven’t been confirmed.</p><p>My individual roles and contributions to the projects have not yet been documented. I’ll update this page when that information is ready to share.</p><a class="text-link" href="../work/index.html">Browse the project index <b>↗</b></a></div></section><section class="section"><p class="eyebrow">THE COLLECTION</p><div class="about-stats"><div><b>{len(shown)}</b><span>projects shown</span></div><div><b>{len(cats)-1}</b><span>broad browse categories</span></div><div><b>{sum(len(man[p["id"]]["screenshots"]) for p in shown)}</b><span>genuine captured views</span></div></div></section></main>'''
(ROOT/'about').mkdir(exist_ok=True)
(ROOT/'about'/'index.html').write_text(shell('About','About Kerollos Harby and the digital work featured in this portfolio.',body,1),encoding='utf-8')

body=f'''<main id="main"><section class="page-hero"><p class="eyebrow">CONTACT</p><h1>Have something<br><em>in mind?</em></h1><p class="lede">Reach out to {esc(K['name'])} using the contact details he shared.</p></section><section class="contact-people"><article><p class="eyebrow">01 · {esc(K['name']).upper()}</p><h2>{esc(K['name'])}</h2><a href="tel:{phone_link(K['phone'])}">{esc(K['phone'])}</a><a href="{esc(K['linkedin'])}" target="_blank" rel="noopener noreferrer">LinkedIn profile ↗</a></article></section><p class="contact-note">Contact details were provided by Kerollos Harby. Individual project roles remain to be confirmed.</p></main>'''
(ROOT/'contact').mkdir(exist_ok=True)
(ROOT/'contact'/'index.html').write_text(shell('Contact','Contact Kerollos Harby by phone or LinkedIn.',body,1),encoding='utf-8')

body='''<main id="main" class="not-found"><p class="eyebrow">404 · PAGE NOT FOUND</p><h1>This page went<br><em>off the map.</em></h1><a class="button lime" href="index.html">Back to the homepage <b>↗</b></a></main>'''
(ROOT/'404.html').write_text(shell('Page not found','The requested page could not be found.',body),encoding='utf-8')

(ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {SITE_URL}/sitemap.xml\n',encoding='utf-8')
urls=['','work/','about/','contact/']+['work/'+p['slug']+'/' for p in shown]
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{SITE_URL}/{u}</loc></url>\n' for u in urls)+'</urlset>',encoding='utf-8')

