JS=r'''(()=>{const input=document.querySelector('#project-search');if(!input)return;const cards=[...document.querySelectorAll('.project-card')],buttons=[...document.querySelectorAll('.filter')],count=document.querySelector('#result-count'),none=document.querySelector('#no-results');let category='All';function update(){const q=input.value.trim().toLowerCase();let n=0;for(const card of cards){const cat=card.querySelector('.card-meta span').textContent;const matchCat=category==='All'||cat===category;const matchText=(card.dataset.search+' '+card.textContent).toLowerCase().includes(q);card.hidden=!(matchCat&&matchText);if(!card.hidden)n++}count.textContent=`${n} ${n===1?'project':'projects'}`;none.hidden=n!==0}buttons.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));update()}));input.addEventListener('input',update);document.querySelector('#reset-search').addEventListener('click',()=>{input.value='';category='All';buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category==='All')));update();input.focus()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();input.focus()}})})();'''

